void cuo_KeyboardInputDto_write(cuo_jw *w, const cuo_KeyboardInputDto *v)
{
    cuo_jw_obj(w);
    cuo_jw_key(w, "Pressed");
    cuo_jw_arr(w);
    for (size_t i = 0; i < v->pressed.len; i++)
        cuo_jw_int(w, v->pressed.items[i]);
    cuo_jw_arr_end(w);
    cuo_jw_obj_end(w);
}

void cuo_KeyboardInputDto_read(const cJSON *json, cuo_KeyboardInputDto *out)
{
    memset(out, 0, sizeof *out);
    {
        const cJSON *a = FIELD(json, "Pressed");
        size_t len = cJSON_IsArray(a) ? (size_t)cJSON_GetArraySize(a) : 0;
        out->pressed.len = len;
        out->pressed.items = len ? cuo_alloc(len * sizeof(*out->pressed.items)) : NULL;
        size_t i = 0;
        for (const cJSON *e = len ? a->child : NULL; e && i < len; e = e->next, i++)
            out->pressed.items[i] = (int32_t)rd_i64(e);
    }
}

