void cuo_Node_write(cuo_jw *w, const cuo_Node *v)
{
    cuo_jw_obj(w);
    cuo_jw_key(w, "Display");
    cuo_jw_uint(w, v->display);
    cuo_jw_key(w, "PositionType");
    cuo_jw_uint(w, v->position_type);
    cuo_jw_key(w, "Overflow");
    cuo_jw_uint(w, v->overflow);
    cuo_jw_key(w, "FlexDirection");
    cuo_jw_uint(w, v->flex_direction);
    cuo_jw_key(w, "JustifyContent");
    cuo_jw_uint(w, v->justify_content);
    cuo_jw_key(w, "AlignItems");
    cuo_jw_uint(w, v->align_items);
    cuo_jw_key(w, "Width");
    cuo_Val_write(w, &v->width);
    cuo_jw_key(w, "Height");
    cuo_Val_write(w, &v->height);
    cuo_jw_key(w, "MinWidth");
    cuo_Val_write(w, &v->min_width);
    cuo_jw_key(w, "MinHeight");
    cuo_Val_write(w, &v->min_height);
    cuo_jw_key(w, "MaxWidth");
    cuo_Val_write(w, &v->max_width);
    cuo_jw_key(w, "MaxHeight");
    cuo_Val_write(w, &v->max_height);
    cuo_jw_key(w, "Left");
    cuo_Val_write(w, &v->left);
    cuo_jw_key(w, "Top");
    cuo_Val_write(w, &v->top);
    cuo_jw_key(w, "Right");
    cuo_Val_write(w, &v->right);
    cuo_jw_key(w, "Bottom");
    cuo_Val_write(w, &v->bottom);
    cuo_jw_key(w, "Padding");
    cuo_UiRect_write(w, &v->padding);
    cuo_jw_key(w, "Border");
    cuo_UiRect_write(w, &v->border);
    cuo_jw_key(w, "Gap");
    cuo_Val_write(w, &v->gap);
    cuo_jw_key(w, "AspectRatio");
    cuo_jw_num(w, v->aspect_ratio);
    cuo_jw_obj_end(w);
}

void cuo_Node_read(const cJSON *json, cuo_Node *out)
{
    memset(out, 0, sizeof *out);
    out->display = (uint8_t)rd_u64(FIELD(json, "Display"));
    out->position_type = (uint8_t)rd_u64(FIELD(json, "PositionType"));
    out->overflow = (uint8_t)rd_u64(FIELD(json, "Overflow"));
    out->flex_direction = (uint8_t)rd_u64(FIELD(json, "FlexDirection"));
    out->justify_content = (uint8_t)rd_u64(FIELD(json, "JustifyContent"));
    out->align_items = (uint8_t)rd_u64(FIELD(json, "AlignItems"));
    cuo_Val_read(FIELD(json, "Width"), &out->width);
    cuo_Val_read(FIELD(json, "Height"), &out->height);
    cuo_Val_read(FIELD(json, "MinWidth"), &out->min_width);
    cuo_Val_read(FIELD(json, "MinHeight"), &out->min_height);
    cuo_Val_read(FIELD(json, "MaxWidth"), &out->max_width);
    cuo_Val_read(FIELD(json, "MaxHeight"), &out->max_height);
    cuo_Val_read(FIELD(json, "Left"), &out->left);
    cuo_Val_read(FIELD(json, "Top"), &out->top);
    cuo_Val_read(FIELD(json, "Right"), &out->right);
    cuo_Val_read(FIELD(json, "Bottom"), &out->bottom);
    cuo_UiRect_read(FIELD(json, "Padding"), &out->padding);
    cuo_UiRect_read(FIELD(json, "Border"), &out->border);
    cuo_Val_read(FIELD(json, "Gap"), &out->gap);
    out->aspect_ratio = (float)rd_num(FIELD(json, "AspectRatio"));
}

