void cuo_ServerGumpDto_write(cuo_jw *w, const cuo_ServerGumpDto *v)
{
    cuo_jw_obj(w);
    cuo_jw_key(w, "Serial");
    cuo_jw_uint(w, v->serial);
    cuo_jw_key(w, "GumpId");
    cuo_jw_uint(w, v->gump_id);
    cuo_jw_key(w, "Page");
    cuo_jw_int(w, v->page);
    cuo_jw_key(w, "X");
    cuo_jw_int(w, v->x);
    cuo_jw_key(w, "Y");
    cuo_jw_int(w, v->y);
    cuo_jw_key(w, "Layout");
    cuo_jw_arr(w);
    for (size_t i = 0; i < v->layout.len; i++)
        cuo_jw_str(w, v->layout.items[i]);
    cuo_jw_arr_end(w);
    cuo_jw_key(w, "Texts");
    cuo_jw_arr(w);
    for (size_t i = 0; i < v->texts.len; i++)
        cuo_jw_str(w, v->texts.items[i]);
    cuo_jw_arr_end(w);
    cuo_jw_key(w, "Buttons");
    cuo_jw_arr(w);
    for (size_t i = 0; i < v->buttons.len; i++)
        cuo_ServerGumpButtonDto_write(w, &v->buttons.items[i]);
    cuo_jw_arr_end(w);
    cuo_jw_key(w, "TextEntries");
    cuo_jw_arr(w);
    for (size_t i = 0; i < v->text_entries.len; i++)
        cuo_ServerGumpTextEntryDto_write(w, &v->text_entries.items[i]);
    cuo_jw_arr_end(w);
    cuo_jw_key(w, "Switches");
    cuo_jw_arr(w);
    for (size_t i = 0; i < v->switches.len; i++)
        cuo_ServerGumpSwitchDto_write(w, &v->switches.items[i]);
    cuo_jw_arr_end(w);
    cuo_jw_obj_end(w);
}

